using System.Text.Json;using ScrapperTrade.Application;using ScrapperTrade.Domain;
namespace ScrapperTrade.Infrastructure;
public sealed class DemoExecutionSimulator:IExecutionAdapter { readonly AccountKind account;readonly TimeSpan age;readonly HashSet<Guid> done=[];public DemoExecutionSimulator(AccountKind a,TimeSpan? maxAge=null)=>(account,age)=(a,maxAge??TimeSpan.FromSeconds(30));public ExecutionResult Execute(ExecutionRequest r){if(account!=AccountKind.Demo)return new(false,"DEMO_ONLY",$"Execution requires positively verified DEMO; observed {account}.");if(DateTimeOffset.UtcNow-r.CreatedAt>age)return new(false,"STALE_COMMAND","Command expired.");if(!done.Add(r.CommandId))return new(false,"DUPLICATE","Command already processed.");return new(true,"SIMULATED_FILL","Order filled by deterministic demo simulator.",Guid.NewGuid());}}
public sealed class JsonAuditStore:IAuditStore { readonly string path;readonly object gate=new();readonly List<AuditEvent> items;public JsonAuditStore(string p){path=p;items=File.Exists(p)?JsonSerializer.Deserialize<List<AuditEvent>>(File.ReadAllText(p))??[]:[];}public void Append(AuditEvent x){lock(gate){items.Add(x);Directory.CreateDirectory(Path.GetDirectoryName(path)!);var tmp=path+".tmp";File.WriteAllText(tmp,JsonSerializer.Serialize(items));File.Move(tmp,path,true);}}public IReadOnlyList<AuditEvent> ReadAll(){lock(gate)return items.ToArray();}}
public sealed class MemoryAuditStore:IAuditStore { readonly List<AuditEvent> items=[];public void Append(AuditEvent x)=>items.Add(x);public IReadOnlyList<AuditEvent> ReadAll()=>items.ToArray();}
